local config = {
  ui_story_31190101_1_dialog_content = "¡Navegador, Navegador!",
  ui_story_31190101_2_dialog_content = "¿Vice? ¿Qué pasa?",
  ui_story_31190101_X2_dialog_content = "¡Algo grande está sucediendo!",
  ui_story_31190101_3_dialog_content = "¡Un extraño cartel apareció en el pasillo!",
  ui_story_31190101_4_dialog_content = "¿Un cartel? ¿Qué tipo de cartel?",
  ui_story_31190101_5_dialog_content = "Está... Es un cartel de madera.",
  ui_story_31190101_X5_dialog_content = "Hay un enorme símbolo de Illumina en un lado.",
  ui_story_31190101_6_dialog_content = "Y alguien ha grabado las palabras <color=#FFB400>\"¡Todos los valientes que quieran desafiar a los más poderosos del Colossus, toquen este cartel, si se atreven!\"</color> en el reverso.",
  ui_story_31190101_7_dialog_content = "¿Significa eso que... alguien en el Colossus está buscando una pelea?",
  ui_story_31190101_8_dialog_content = "No lo sé...",
  ui_story_31190101_9_dialog_content = "Pero si la experiencia sirve de algo, ¡parece que alguien está creando problemas de nuevo!",
  ui_story_31190101_11_dialog_content = "¿Ves? Es justo aquí...",
  ui_story_31190101_12_dialog_content = "Sí. Lo veo.",
  ui_story_31190101_13_dialog_content = "¿Podría ser algún tipo de desafío de alguien en el Colossus?",
  ui_story_31190101_14_dialog_content = "Este desafío... ¡Parece que podríamos tener algún problema serio en nuestras manos!",
  ui_story_31190101_15_dialog_content = "Si se produce una pelea en el Colossus, ¡quién sabe lo graves que serán los daños!",
  ui_story_31190101_16_dialog_content = "Y si acaban dañando las instalaciones del Colossus... ¡Sólo pensar en las facturas de las reparaciones hace que me duela la cabeza!",
  ui_story_31190101_17_dialog_content = "Navegador, nuestros ahorros están en juego aquí...",
  ui_story_31190101_18_dialog_content = "Vice, trata de calmarte un poco...",
  ui_story_31190101_19_dialog_content = "¡Lo estoy intentando! Pero realmente, ¿quién haría algo así en el Colossus?",
  ui_story_31190101_20_dialog_content = "Vice, todavía no ha pasado nada. No te dejes llevar.",
  ui_story_31190101_21_dialog_content = "¡Tu cola se agita por todos lados!",
  ui_story_31190101_22_dialog_content = "Hey... ¿Qué fue ese sonido?",
  ui_story_31190101_23_dialog_content = "Tu cola... derribó el cartel de madera.",
  ui_story_31190101_24_dialog_content = "Así que fuiste tú... ¿Te atreves a desafiar a la más poderosa del Colossus—<color=#FFB400>Revy</color>?",
  ui_story_31190101_25_dialog_content = "¡Eeeek!",
  ui_story_31190101_26_dialog_content = "Sí, Vice, la arquera de cola larga, has venido aquí a desafiarme, ¿verdad?",
  ui_story_31190101_27_dialog_content = "No, no, no...",
  ui_story_31190101_28_dialog_content = "¡Mira, Revy! ¡No quiero desafiar a nadie! Mi cola derribó accidentalmente el cartel, ¿ves?",
  ui_story_31190101_29_dialog_content = "Espera... ¿\"Desafiarme\"? ¿Quieres decir que fuiste tú quien puso este cartel aquí?",
  ui_story_31190101_30_dialog_content = "Por supuesto, yo lo hice.",
  ui_story_31190101_31_dialog_content = "Entonces, eso significa... Revy, ¿eres tu la más poderosa del Colossus?",
  ui_story_31190101_32_dialog_content = "¿Tú también lo crees? ¡Ah, pero por supuesto! Las mentes heroicas piensan igual.",
  ui_story_31190101_33_dialog_content = "Ajaja... Entonces, ¿estás esperando aquí a que alguien te desafíe?",
  ui_story_31190101_34_dialog_content = "Sí, y tú eres la primera en tocar ese cartel de madera.",
  ui_story_31190101_35_dialog_content = "Cierto... ¡Pero Revy, apareciste en el momento en que lo toqué!",
  ui_story_31190101_36_dialog_content = "Sí... ¿Cómo supiste que fue Vice quien lo tocó en primer lugar?",
  ui_story_31190101_37_dialog_content = "¿Es algún tipo de nueva tecnología de Illumina que no conocemos?",
  ui_story_31190101_38_dialog_content = "Bueno, escondida justo ahí y acechando en las sombras, estaba...",
  ui_story_31190101_39_dialog_content = "¿Acechando en las sombras? ¿Quieres decir que has estado observando en secreto para ver quién tocaba tu cartel...?",
  ui_story_31190101_40_dialog_content = "Correcto... ¿Era tan obvio?",
  ui_story_31190101_41_dialog_content = "Y fue Vice quien tocó mi cartel de madera primero.",
  ui_story_31190101_42_dialog_content = "Así que ahora, Vice debe desafiarme. ¡Que esta batalla decida, de una vez por todas, quién es la más poderosa!",
  ui_story_31190101_43_dialog_content = "Pero Revy... Emm... En realidad fue sólo un pequeño accidente...",
  ui_story_31190101_44_dialog_content = "Pero aún así lo tocaste.",
  ui_story_31190101_45_dialog_content = "Hmm... ¿Qué tal si nos saltamos el desafío y acordamos que tú eres la más poderosa?",
  ui_story_31190101_46_dialog_content = "¡Eso no servirá! ¡Sólo a través del combate mortal puedo demostrar que soy digna del título \"La más poderosa del Colossus\"!",
  ui_story_31190101_47_dialog_content = "¿Cómo me he metido en este lío...?",
  ui_story_31190101_48_dialog_content = "¿Estás lista para comenzar nuestro duelo predestinado?",
  ui_story_31190101_49_dialog_content = "Erm, Revy... ¿Qué tal si bajas tu arma, y tratamos de hablar de esto...?",
  ui_story_31190101_50_dialog_content = "Muy bien.",
  ui_story_31190101_51_dialog_content = "La cuestión es, que todos los que vivimos en el Colossus estamos del mismo lado. No hay necesidad de andar desafiándonos unos a otros ...",
  ui_story_31190101_52_dialog_content = "Y lo que es más... ¡Las dos somos soldados de Illumina!",
  ui_story_31190101_53_dialog_content = "Los soldados también deben perfeccionar sus habilidades de combate entre ellos.",
  ui_story_31190101_54_dialog_content = "¡Y eso va doblemente para los soldados en el frente! ¡Acostumbrarnos a la sangre fresca y a las furiosas llamas de la batalla, debemos!",
  ui_story_31190101_55_dialog_content = "¿Ah? ¿Quieres decir que quieres hacerme... Sangrar?",
  ui_story_31190101_56_dialog_content = "Estaba pensando en ello.",
  ui_story_31190101_57_dialog_content = "Creo que deberíamos guardar nuestras fuerzas para luchar contra los Eclipsites, juntas...",
  ui_story_31190101_58_dialog_content = "Esa sería una forma mucho mejor de fortalecernos que esta competición tuya... ¿Qué dices?",
  ui_story_31190101_59_dialog_content = "No puedo negar que hay algo de verdad en tus palabras, pero no veo nada malo en promover un poco de sana competencia.",
  ui_story_31190101_60_dialog_content = "Ustedes dos, ¿qué tal si nos tomamos un descanso y hablamos de esto más tarde?",
  ui_story_31190101_61_dialog_content = "¡Hora de descanso! ¡Hora de descanso!",
  ui_story_31190101_62_dialog_content = "¡Concurso! ¡Error! ¡Error!",
  ui_story_31190101_63_dialog_content = "¡Concurso, confirmado!",
  ui_story_31190101_64_dialog_content = "¡Incorrecto! ¡Error! ¡Comenzando reparaciones!",
  ui_story_31190101_65_dialog_content = "¡Error del mecanismo de reparación! ¡Error del mecanismo de reparación!",
  ui_story_31190101_66_dialog_content = "Oh no... Son las luciérnagas.",
  ui_story_31190101_67_dialog_content = "Ahora sus grabaciones y los sonidos del sistema están revueltos. Qué problema...",
  ui_story_31190101_68_dialog_content = "¿Puedes parar? ¡Me estás dando dolor de cabeza!",
  ui_story_31190101_69_dialog_content = "¡Navegador! No estoy tratando de causar un dolor de cabeza a nadie... Sólo estábamos participando en una discusión razonable. ¡Los aliados nunca deben pelear!",
  ui_story_31190101_70_dialog_content = "Deberías saber que detesto las discusiones...",
  ui_story_31190101_71_dialog_content = "¿Y pelear? Dije que simplemente deberíamos participar en una competencia amistosa. Aunque, algunos podrían decir que no hay diferencia en el significado de estas dos palabras.",
  ui_story_31190101_72_dialog_content = "¡No hay diferencia! ¡Especialmente cuando se habla de sangre!",
  ui_story_31190101_73_dialog_content = "¿Mmm? ¿En serio? Tal vez... Pero ese no es el punto.",
  ui_story_31190101_74_dialog_content = "¡Hey, no estaba hablando de ustedes dos!",
  ui_story_31190101_75_dialog_content = "¡Ustedes dos! ¡Ustedes dos!",
  ui_story_31190101_76_dialog_content = "(Esto es una pesadilla... Las cosas se están saliendo de control aquí...)",
  ui_story_31190101_77_dialog_content = "(¡Eso es!)",
  ui_story_31190101_X77_dialog_content = "(Siempre me desmayo, ¿verdad? ¡Podría usarlo para poner fin a todo esto!)",
  ui_story_31190101_78_dialog_content = "Vice... Revy... Deja de discutir...",
  ui_story_31190101_79_dialog_content = "Yo...",
  ui_story_31190101_80_dialog_content = "¡Oh no! ¡Navegador! ¡Navegador! ¿¡Te has desmayado!?",
  ui_story_31190101_81_dialog_content = "¿Mi poderosa presencia fue demasiado para el débil Navegante?",
  ui_story_31190101_82_dialog_content = "<color=#e8d9bb> Vice y Reventon te llevan de regreso a tu habitación... </color>",
  ui_story_31190101_83_dialog_content = "<color=#e8d9bb>Varias horas después...</color>",
  ui_story_31190101_84_dialog_content = "Wow... En verdad funcionó.",
  ui_story_31190101_85_dialog_content = "Y evité que se produjera una pelea en el Colossus...",
  ui_story_31190101_86_dialog_content = "¿Eh? ¿Quién?",
  ui_story_31190101_87_dialog_content = "Soy yo. Veo que estás despierto.",
  ui_story_31190101_88_dialog_content = "Oh... Pasa adelante...",
  ui_story_31190101_89_dialog_content = "¿Te sientes mejor?",
  ui_story_31190101_90_dialog_content = "Más o menos.",
  ui_story_31190101_91_dialog_content = "Entonces, la razón por la que te desmayaste fue porque quería participar en un desafío y luchar a bordo del Colossus ... ¿verdad?",
  ui_story_31190101_92_option_content = "¡Esa no es la razón!",
  ui_story_31190101_93_dialog_content = "¿En serio? Pero una mención a la lucha y te apagaste como una luz.",
  ui_story_31190101_94_option_content = "Correcto.",
  ui_story_31190101_95_dialog_content = "Tal y como sospechaba.",
  ui_story_31190101_96_dialog_content = "Bueno, he quitado el cartel de madera.",
  ui_story_31190101_97_dialog_content = "Mientras no te proponga otro desafío, no te desmayarás de nuevo, ¿verdad?",
  ui_story_31190101_98_dialog_content = "¡Sí, tienes razón!",
  ui_story_31190101_99_dialog_content = "Mmm. Ya veo.",
  ui_story_31190101_100_dialog_content = "Pues bien, me despediré.",
  ui_story_31190101_101_dialog_content = "<color=#e8d9bb>Unos días después.</color>",
  ui_story_31190101_102_dialog_content = "*Timbrando*",
  ui_story_31190101_103_dialog_content = "¿No es todavía la hora del almuerzo...? ¿Acabo de soñar que suena una alarma...?",
  ui_story_31190101_104_dialog_content = "¿Destellos de luciérnagas...? Eso significa...",
  ui_story_31190101_105_dialog_content = "¡Esto no es un sueño!",
  ui_story_31190101_106_dialog_content = "¿Qué está pasando?",
  ui_story_31190101_107_dialog_content = "¡Salón! ¡Fallo en la reparación del saco de arena! ¡Salón! ¡Fallo en la reparación del saco de arena!",
  ui_story_31190101_108_dialog_content = "Uf... Por lo que puedo ver, Soroz sigue de una pieza...",
  ui_story_31190101_109_dialog_content = "Será mejor que vaya a revisar el Salón.",
  ui_story_31190101_110_dialog_content = "<color=#e8d9bb>Un fuerte ruido proviene del Salón.</color>",
  ui_story_31190101_111_dialog_content = "Ahora, la <color=#FFB400>Asamblea de Aniquilación de Eclipsites</color> entra en su última sesión interactiva.",
  ui_story_31190101_112_dialog_content = "Tú allí-explica cómo harías para matar una Eclipsite, y demuéstranos tu método en esos sacos de arena.",
  ui_story_31190101_113_dialog_content = "Tal y como te mostré.",
  ui_story_31190101_114_dialog_content = "¡Ja! ¡Una vez conduje un camión blindado sobre una Eclipsite!",
  ui_story_31190101_X114_dialog_content = "¡Justo así!",
  ui_story_31190101_115_dialog_content = "¿Alguna vez has olido el jugo de Eclipsites? ¡Eso no es para los débiles de corazón!",
  ui_story_31190101_116_dialog_content = "Saco de arena—el saco explotó y la arena se desbordó ... ¡Intentando reparar! ¡Intentando reparar!",
  ui_story_31190101_117_dialog_content = "Normalmente uso mi magia para matar a esas cosas.",
  ui_story_31190101_118_dialog_content = "Cierran los ojos y no viven más. Creo que es un método muy simple y directo.",
  ui_story_31190101_X118_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_31190101_119_dialog_content = "¡Saco de arena desatado! ¡Intentando reparar! ¡Intentando reparar!",
  ui_story_31190101_120_dialog_content = "¿Eclipsites? Sólo agarro mi arma y aprieto el gatillo hasta que hace... \"clic.\" Je...",
  ui_story_31190101_121_dialog_content = "¡Saco de arena-fuga detectada! ¡Intentando reparar! ¡Intentando reparar!",
  ui_story_31190101_122_dialog_content = "Por aquel entonces, los chicos y yo nos lanzábamos contra hordas de esas cosas sin llevarnos ni un rasguño...",
  ui_story_31190101_123_dialog_content = "¡Los atacábamos tan rápido, que esas cosas se quedaban paradas durante unos segundos antes de darse cuenta de lo que estaba pasando! Luego vino la carrera... Tsk...",
  ui_story_31190101_124_dialog_content = "¡Sacos de arena reparados con éxito! ¡No se han localizado roturas!",
  ui_story_31190101_X124_dialog_content = "¡Ja!",
  ui_story_31190101_125_dialog_content = "¡Saco-de arena destruida! ¡Fallo! ¡Reparaciones fallida! ¡Reparaciones fallida!",
  ui_story_31190101_126_dialog_content = "He hecho un registro oficial de todas sus contribuciones. Has compartido 265 formas diferentes de matar Eclipsites.",
  ui_story_31190101_127_dialog_content = "Todos parecen satisfechos por ahora. Continuemos nuestra colaboración la próxima vez.",
  ui_story_31190101_128_dialog_content = "¡Y con eso, por la presente declaro que esta reunión ha terminado!",
  ui_story_31190101_129_dialog_content = "Por suerte, parece que están teniendo algún tipo de... Discusión...",
  ui_story_31190101_130_dialog_content = "<color=#e8d9bb>Después de volver a su habitación...</color>",
  ui_story_31190101_131_dialog_content = "Veinte sacos de arena rotos.",
  ui_story_31190101_132_dialog_content = "<anim type=Shake><size=45>¡¡¡Veinte sacos de arena rotos!!!</size></anim>",
  ui_story_31190101_133_dialog_content = "Yo sé...",
  ui_story_31190101_134_dialog_content = "¡Deberías alegrarte de que eso sea todo lo que se rompió!",
  ui_story_31190101_135_dialog_content = "Olvídalo. Mientras no peleen entre ellos en el Colossus, puedo llevarme veinte sacos de arena rotos cualquier día.",
  ui_story_31190101_136_dialog_content = "<color=#e8d9bb>El día siguiente.</color>",
  ui_story_31190101_137_dialog_content = "Emm... ¿Estás ahí?",
  ui_story_31190101_138_dialog_content = "Aquí estoy. ¿Qué pasa, Revy?",
  ui_story_31190101_139_dialog_content = "Tus luciérnagas transmitieron repetidamente... mis hazañas... a lo largo del Colossus ayer.",
  ui_story_31190101_140_dialog_content = "¿Hazañas?",
  ui_story_31190101_141_dialog_content = "Los sacos de arena rotos.",
  ui_story_31190101_142_dialog_content = "Me disculpo.",
  ui_story_31190101_143_dialog_content = "Ayer destruimos veinte sacos de arena. Si Vice no nos hubiera detenido, aún más habrían corrido la misma suerte.",
  ui_story_31190101_144_dialog_content = "Eso no es correcto. Una disculpa así no parece lo suficientemente formal. Antes de venir aquí, le pregunté específicamente a Vice cómo disculparse sinceramente.",
  ui_story_31190101_145_dialog_content = "Ahem... Siento mucho la gran pérdida que os causé ayer a ti y al Colossus, Navegador, lo siento.",
  ui_story_31190101_146_dialog_content = "No hay necesidad de ser tan formal...",
  ui_story_31190101_147_dialog_content = "Realmente no es un gran problema. Mientras no luches en el Colossus, todo lo demás me parece bien.",
  ui_story_31190101_148_dialog_content = "¿En serio?",
  ui_story_31190101_149_dialog_content = "Cuando dices que no es para tanto, ¿quieres decir que no estás enfadado?",
  ui_story_31190101_150_option_content = "Por supuesto.",
  ui_story_31190101_151_dialog_content = "Veo que no has malinterpretado mis intenciones, ¡ya veo!",
  ui_story_31190101_152_option_content = "Estoy un poco enfadado, para ser sincero...",
  ui_story_31190101_153_dialog_content = "Entonces, por favor, siéntase libre de desatar su furia sobre mí.",
  ui_story_31190101_154_dialog_content = "Realmente no teníamos la intención de dañar su Colossus. Sólo quería probar...",
  ui_story_31190101_155_dialog_content = "Lo se.",
  ui_story_31190101_156_dialog_content = "Demostrar que soy la más poderosa del Colossus...",
  ui_story_31190101_157_dialog_content = "Sea como sea, los aliados nunca deben luchar entre sí... ¡especialmente en el Colossus!",
  ui_story_31190101_158_dialog_content = "Cumplir con esta declaración, lo haré... muy probablemente.",
  ui_story_31190101_159_dialog_content = "<color=#e8d9bb>Un día después, cuando Soroz está a punto de aterrizar...</color>",
  ui_story_31190101_160_dialog_content = "¿Ah? Hay algo en la puerta.",
  ui_story_31190101_161_dialog_content = "Firmado—Maestra de la Alter-Blade, Mecánica Soberana y Vanguardia Suprema del Colossus—Revy.",
  ui_story_31190101_162_dialog_content = "Veamos qué tenemos aquí...",
  ui_story_31190101_163_dialog_content = "¡Caramba! ¿Qué es ese horrible olor?",
  ui_story_31190101_164_dialog_content = "Hay una nota dentro...",
  ui_story_31190101_165_dialog_content = "\"Ya que no puedo desafiar a mis aliados ni luchar en el Colossus...”",
  ui_story_31190101_166_dialog_content = "\"Una vez que aterricemos, desafiaré al líder de mis aliados: ¡el Celestita!”",
  ui_story_31190101_167_dialog_content = "Urgh, siento que este olor va a hacer que me desmaye de nuevo...",
  ui_story_31190101_X167_dialog_content = "...",
  ui_story_31190101_168_dialog_content = "En realidad, teniendo en cuenta el desafío de Revy, tal vez desmayarse no sería algo tan malo ahora...",
  ui_story_31190601_1_dialog_content = "Gracias a ti, pudimos identificar al ladrón en poco tiempo.",
  ui_story_31190601_2_dialog_content = "Su ayuda es muy apreciada. Tenga la seguridad de que recibirá el castigo que se merece...",
  ui_story_31190601_3_dialog_content = "Solo estaba haciendo lo que sentía que debía hacer. ¡Siempre estoy feliz de ayudar!",
  ui_story_31190601_4_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_31190601_5_dialog_content = "¿Eh? ¿Que fue ese ruido?",
  ui_story_31190601_6_dialog_content = "Sonaba como si alguien, no, como si un par de personas acabaran de caer al suelo.",
  ui_story_31190601_7_dialog_content = "Ah, debe ser el chico nuevo otra vez. Lo juro, desde que llegó aquí, parece que nunca se detiene...",
  ui_story_31190601_8_dialog_content = "¿El \"niño nuevo\"? No creo que un niño pueda estar haciendo ese tipo de ruido...",
  ui_story_31190601_9_dialog_content = "Je, yo tampoco lo creería si no lo hubiera visto por mí mismo.",
  ui_story_31190601_10_dialog_content = "El día que llegó, fui a su celda a llevarle la comida. En ese momento, todo parecía perfectamente normal.",
  ui_story_31190601_11_dialog_content = "Pero cuando regresé para recoger su bandeja, todos los demás en la celda habían sido noqueados por ese mocoso loco.",
  ui_story_31190601_12_dialog_content = "Y mientras yacían inconscientes por todo el suelo, ella estaba sentada a un lado, comiendo como si nada hubiera pasado.",
  ui_story_31190601_13_dialog_content = "Suspiro... La hemos reubicado 16 veces hasta ahora. A este ritmo, el único lugar para ella será el confinamiento solitario.",
  ui_story_31190601_14_dialog_content = "Espera, me estás diciendo... ¡¿Una niña peleó y ganó contra todos los convictos en 15 celdas de prisión?!",
  ui_story_31190601_15_dialog_content = "(Una niña increíblemente poderosa a la que le encanta pelear... Tengo un mal presentimiento sobre esto...)",
  ui_story_31190601_16_dialog_content = "Así es, es por eso que realmente debería ir a echar un vistazo a lo que sucedió esta vez.",
  ui_story_31190601_17_dialog_content = "Lo siento, pero tendrás que salir tú mismo. Sabes dónde está la salida, ¿verdad?",
  ui_story_31190601_18_dialog_content = "Er, si no es mucha molestia... ¿Puedo ir contigo?",
  ui_story_31190601_19_dialog_content = "¿Conmigo?",
  ui_story_31190601_20_dialog_content = "¡P-Por favor, no te hagas una idea equivocada! ¡Te prometo que no estoy tramando nada!",
  ui_story_31190601_21_dialog_content = "Es solo que tengo la sensación de que podría ayudarte con esto.",
  ui_story_31190601_22_dialog_content = "Bueno... Noqueate a ti mismo, chico.",
  ui_story_31190601_23_dialog_content = "Sobre todo porque ya nos has ayudado un montón y todo eso. Si alguien pregunta, solo diré que nos desviamos rápidamente al salir.",
  ui_story_31190601_24_dialog_content = "Pero nada divertido, ¿entendido? De lo contrario, es mi cabeza en el tajo.",
  ui_story_31190601_25_dialog_content = "¡Entendido!",
  ui_story_31190601_26_dialog_content = "¿No me digas que no quedan más células?",
  ui_story_31190601_27_dialog_content = "Esto fue una decepción más grande de lo que pensé... ¿Podría haberme vuelto mucho más fuerte ya?",
  ui_story_31190601_28_dialog_content = "(Espera, eso suena como...)",
  ui_story_31190601_29_dialog_content = "¿Revisado?",
  ui_story_31190601_30_dialog_content = "¿Eh? Oh hola PlayerName! ¿También te arrestaron?",
  ui_story_31190601_31_dialog_content = "¿Ustedes dos se conocen?",
  ui_story_31190601_32_dialog_content = "Sí... Bastante, en realidad...",
  ui_story_31190601_33_dialog_content = "Sabes, siempre te consideré el tipo de héroe bueno y bueno, como el personaje principal de un cómic. ¡Nunca pensé que te vería en la cárcel algún día!",
  ui_story_31190601_34_dialog_content = "Pero ya que estás aquí... Supongo que no tengo más remedio que noquearte también.",
  ui_story_31190601_35_dialog_content = "¡Yo no fui arrestado en absoluto! Solo vine a identificar a un sospechoso en un robo.",
  ui_story_31190601_36_dialog_content = "Espera un segundo. ¿Golpeaste a todos estos convictos aquí... tú solo?",
  ui_story_31190601_37_dialog_content = "¡Así es!",
  ui_story_31190601_38_dialog_content = "Así que el guardia no estaba bromeando... ¡¿En serio golpeaste a cada uno de los prisioneros en toda la cárcel por tu cuenta?!",
  ui_story_31190601_39_dialog_content = "Sí, pero estos tipos no eran tan divertidos como los de las últimas quince celdas. ¡Apenas los toqué antes de que cayeran directamente al suelo!",
  ui_story_31190601_40_dialog_content = "Increíble... ¡Ni una sola persona en esta apestosa cárcel de Umbraton sabe pelear!",
  ui_story_31190601_41_dialog_content = "¡E-Esta instalación solo está destinada a albergar a delincuentes menores! Pero a juzgar por los últimos dos días, tampoco creo que este sea el lugar adecuado para ti...",
  ui_story_31190601_42_dialog_content = "¿Eh? ¿Me vas a dejar ir, entonces?",
  ui_story_31190601_43_dialog_content = "¡En tus sueños! ¡En solo dos días, lograste vencer a todos los reclusos de este lugar!",
  ui_story_31190601_44_dialog_content = "Al principio pensé que era porque no te llevabas bien con los presos de la primera celda. ¡Pero resulta que tenías un hueso para elegir con cada persona en todo el maldito lugar!",
  ui_story_31190601_45_dialog_content = "Si no se te ocurre una mejor excusa para toda esta pelea, no tendré más remedio que transferirte a confinamiento solitario.",
  ui_story_31190601_46_dialog_content = "...",
  ui_story_31190601_47_dialog_content = "Última oportunidad, chico, ¿por qué te peleaste con cada uno de tus compañeros de celda?",
  ui_story_31190601_48_dialog_content = "(Sigue mirándome... ¿Hay algo que no pueda decirle al guardia?)",
  ui_story_31190601_49_dialog_content = "¿S-señor? ¿Podemos tener un momento para hablar en privado?",
  ui_story_31190601_50_dialog_content = "Solo necesito diez minutos. ¡Por favor confia en mi!",
  ui_story_31190601_51_dialog_content = "Puedes vigilarnos desde el otro lado de la celda. ¡Te prometo que no romperé ninguna ley!",
  ui_story_31190601_52_dialog_content = "... Multa. De todos modos, tengo que llamar al médico de la prisión.",
  ui_story_31190601_53_dialog_content = "También hay guardias apostados en la puerta, así que ni siquiera intentes escapar.",
  ui_story_31190601_54_dialog_content = "Gracias por su confianza, señor.",
  ui_story_31190601_55_dialog_content = "El guardia se fue hace mucho, Revy. Creo que ahora puedes hablar libremente.",
  ui_story_31190601_56_dialog_content = "A-Sobre que? No tengo idea de lo que estás hablando...",
  ui_story_31190601_57_dialog_content = "¡Estoy hablando de la razón por la que comenzaste una pelea en prisión!",
  ui_story_31190601_58_dialog_content = "¡Te encerrarán solo si no dices la verdad!",
  ui_story_31190601_59_dialog_content = "... Bien, pero solo te lo digo a ti.",
  ui_story_31190601_60_dialog_content = "Ya que es tan importante para ti... Solo estaba <color=#FFB400>jugando con las reglas de la prisión</color>, eso es todo.",
  ui_story_31190601_61_dialog_content = "¿\"Reglas de la prisión\"...?",
  ui_story_31190601_62_dialog_content = "¡Sí!",
  ui_story_31190601_63_dialog_content = "Mira, no hay tienda en la prisión. No puedes simplemente comprar lo que quieras.",
  ui_story_31190601_64_dialog_content = "Si realmente quieres algo aquí, se lo quitas a otra persona... Por la fuerza, si es necesario.",
  ui_story_31190601_65_dialog_content = "Y esas son las reglas de la prisión, en pocas palabras.",
  ui_story_31190601_66_dialog_content = "Si ese es el caso, ¿por qué no se lo dijiste al guardia? Estoy seguro de que ya lo ha visto todo.",
  ui_story_31190601_67_dialog_content = "Ahora no es el momento adecuado para decírselo. Todavía estoy súper frustrado y molesto.",
  ui_story_31190601_68_dialog_content = "¿Por qué razón? Revy, has enviado a todos aquí tirados. ¿No conseguiste lo que querías?",
  ui_story_31190601_69_dialog_content = "¡Solo es eso! ¡Los vencí a todos, a todos! Eso es lo que es tan molesto.",
  ui_story_31190601_70_dialog_content = "¡Pero mi objetivo y mi razón para ir a la cárcel en primer lugar ni siquiera ha llegado todavía! ¡Todavía no he conseguido lo que vine a buscar!",
  ui_story_31190601_71_dialog_content = "<size=45>¡¿Te enviaste a la cárcel solo para poder recuperar algo?!</size>",
  ui_story_31190601_72_dialog_content = "¡¿Qué diablos es tan importante que estarías dispuesto a ir a prisión por ello?!",
  ui_story_31190601_73_dialog_content = "Bueno, ya que eres tú, supongo que podría decirte, PlayerName.",
  ui_story_31190601_74_dialog_content = "Es un tesoro legendario, uno que innumerables personas han perseguido. ¡Un tesoro que ha superado incluso al más grande de los guerreros de la historia!",
  ui_story_31190601_75_dialog_content = "Solo un olfateo hará que el cuero cabelludo de cualquiera se pique y se queme...",
  ui_story_31190601_76_dialog_content = "Y solo un sabor hará que toda tu cabeza se ponga roja y sudorosa...",
  ui_story_31190601_77_dialog_content = "Pero aun así, la gente no puede resistir su poder y seguirá devorándolo como un grupo de adictos enloquecidos...",
  ui_story_31190601_78_dialog_content = "¡E-Espera un minuto!",
  ui_story_31190601_79_dialog_content = "Lo que estás describiendo suena demasiado peligroso...",
  ui_story_31190601_80_dialog_content = "¿Estás seguro de que sabes lo que estás haciendo?",
  ui_story_31190601_81_dialog_content = "¿Qué estás diciendo? estoy hablando de la <color=#FFB400>Salsa Picante Súper Ardiente</color>!",
  ui_story_31190601_82_dialog_content = "¿Eh? ¿Estabas hablando de salsa picante?",
  ui_story_31190601_83_dialog_content = "¿Qué más podría ser? Solo hay una cosa que coincide con mi descripción, y es la salsa picante Super Blazing.",
  ui_story_31190601_84_dialog_content = "Verás, \"picante\" no es solo un sabor. Es una especie de dolor.",
  ui_story_31190601_85_dialog_content = "Comer alimentos picantes hace que tu cuerpo produzca constantemente adrenalina y otras endorfinas, que a su vez te hacen sentir excitación y satisfacción.",
  ui_story_31190601_86_dialog_content = "¡Con este material, podrás seguir avanzando incluso después de que tu lengua se entumezca por completo!",
  ui_story_31190601_87_dialog_content = "Ah, cuanto más hablo de ello, más quiero probar su impactante delicia... ¡Lo deseo tanto!",
  ui_story_31190601_88_dialog_content = "Entonces, ¿la razón por la que golpeaste a todos estos prisioneros... fue solo para conseguir alguna salsa picante especial?",
  ui_story_31190601_89_dialog_content = "En primer lugar, se llama <color=#FFB400>Salsa Picante Súper Ardiente</color>.",
  ui_story_31190601_90_dialog_content = "En segundo lugar, ¡te acabo de decir que innumerables personas solo han soñado con tenerlo! ¡Haría cualquier cosa solo por poner mis manos en algunos!",
  ui_story_31190601_91_dialog_content = "Quiero decir, te creo allí... Después de todo, incluso estabas dispuesto a ir a la cárcel por eso. Me pregunto si la abuela alguna vez ha oído hablar de...",
  ui_story_31190601_92_dialog_content = "<size=45>¡¡¡Alto!!!</size>",
  ui_story_31190601_93_dialog_content = "Él, eh... no sabe que estoy aquí.",
  ui_story_31190601_94_dialog_content = "Estaba ayudando al viejo Gram a comprar algunos ingredientes en Umbraton cuando escuché a algunas personas hablar sobre salsa picante.",
  ui_story_31190601_95_dialog_content = "No pude evitarlo, así que me acerqué para escuchar más. Nunca esperé escucharlos mencionar <color=#FFB400>Salsa Picante Súper Ardiente</color> aunque.",
  ui_story_31190601_96_dialog_content = "Uno de ellos dijo que se sirve casi exclusivamente en las cárceles.",
  ui_story_31190601_97_dialog_content = "Con su poderoso sabor, una sola gota es todo lo que necesitas para un plato completo de comida. Originalmente, fue especialmente diseñado como el mejor condimento para la comida de la prisión.",
  ui_story_31190601_98_dialog_content = "Como resultado de su increíble sabor, se convirtió en una forma de moneda fuerte dentro del sistema penitenciario.",
  ui_story_31190601_99_dialog_content = "Con una sola botella de <color=#FFB400>Salsa Picante Súper Ardiente</color>, una persona podría cambiarlo por cualquier cosa que pudiera desear en prisión.",
  ui_story_31190601_100_dialog_content = "Pero incluso después de vencer a todos estos prisioneros, todavía no he visto ni una gota de eso...",
  ui_story_31190601_101_dialog_content = "¡Han pasado diez minutos! Tu pequeña \"visita\" ha terminado.",
  ui_story_31190601_102_dialog_content = "¡Llega justo a tiempo, señor!",
  ui_story_31190601_103_dialog_content = "No pude encontrar lo que quería aquí, así que puedes dejarme ir ahora.",
  ui_story_31190601_104_dialog_content = "Bueno, dado lo pequeño que fue tu crimen en primer lugar, podría haberte dejado ir ya...",
  ui_story_31190601_105_dialog_content = "Pero después de verte golpear a cada uno de los prisioneros que tenemos en este lugar, me temo que tendrás que quedarte un poco más.",
  ui_story_31190601_106_dialog_content = "<size=45>¡¿Qué?! ¡¿Me estás tomando el pelo?!</size>",
  ui_story_31190601_107_dialog_content = "Ahora que estamos en el tema, ¿qué hiciste exactamente para que te metieran en la cárcel, Revy?",
  ui_story_31190601_108_dialog_content = "No quería infringir la ley ni nada... Sólo quería entrar aquí.",
  ui_story_31190601_109_dialog_content = "Así que me paré frente a un patrullero, saqué una señal de tráfico del suelo y luego la volví a colocar en su lugar varias veces.",
  ui_story_31190601_110_dialog_content = "Después de eso, me acusaron de vandalismo a la propiedad pública y me tiraron aquí.",
  ui_story_31190601_111_dialog_content = "Supongo que eso explica mucho sobre la naturaleza de los crímenes de los convictos aquí...",
  ui_story_31190601_112_dialog_content = "Tengo que transportar a todos estos prisioneros a la sala médica. Esta noche, tienes que sentarte aquí solo y pensar en lo que has hecho.",
  ui_story_31190601_113_dialog_content = "E-Espere, señor. Solo por curiosidad, ¿alguna vez has oído hablar de cierta... salsa picante súper picante?",
  ui_story_31190601_114_dialog_content = "Se llama <color=#FFB400>Salsa Picante Súper Ardiente</color>!",
  ui_story_31190601_115_dialog_content = "S-Sí, eso. Escuché que sabe increíble y que se usa como moneda fuerte en las cárceles.",
  ui_story_31190601_116_dialog_content = "¿Qué salsa, ahora? Nunca he oído hablar de nada por el estilo.",
  ui_story_31190601_117_dialog_content = "Además, las cárceles de Umbraton usan carne enlatada como moneda fuerte.",
  ui_story_31190601_118_dialog_content = "<size=45>¿¡¿Qué?!?</size>",
  ui_story_31190601_119_dialog_content = "Pero, ¿cómo podría ser esto...? ¿Cómo podría una prisión no tener mi salsa picante legendaria...?",
  ui_story_31190601_120_dialog_content = "... ¿Estás bien, Revy?",
  ui_story_31190601_121_dialog_content = "Parece que tu alma te ha dejado...",
  ui_story_31190601_122_dialog_content = "Yo... estaré bien...",
  ui_story_31190601_123_dialog_content = "PlayerName... Realmente podría ir por algo de la comida casera de la abuela ahora mismo...",
  ui_story_31190601_124_option_content = "No te preocupes. ¡Veré qué puedo hacer para sacarte!",
  ui_story_31190601_125_dialog_content = "¿Eh, señor? Dijiste que su crimen fue lo suficientemente leve como para dejarla ir, ¿verdad?",
  ui_story_31190601_126_dialog_content = "Además, su pequeña pelea con los otros prisioneros debe considerarse parte de las \"reglas de la prisión\" tácitas aquí.",
  ui_story_31190601_127_dialog_content = "¿Hay alguna posibilidad de que puedas...",
  ui_story_31190601_128_dialog_content = "No. Pero te lo haré saber de inmediato una vez que esté libre para irse.",
  ui_story_31190601_129_dialog_content = "Ya veo... Lo siento, Revy. Está fuera de mis manos.",
  ui_story_31190601_130_option_content = "Lo siento, no puedo ayudarte a salir.",
  ui_story_31190601_131_dialog_content = "Quiero decir, criminales o no, atacaste a todas estas personas...",
  ui_story_31190601_132_dialog_content = "P-Pero no te preocupes! ¡Me aseguraré de traerte algo de la comida de la abuela tan pronto como te dejen salir!",
  ui_story_31190601_133_dialog_content = "Suspiro... lo sabía. Supongo que realmente no puedes contar con nadie más que contigo mismo, ¿eh?",
  ui_story_31190601_134_dialog_content = "Menos mal que comencé a prepararme para este día hace años.",
  ui_story_31190601_135_dialog_content = "¿Qué tipo de persona se prepara para estar un día en la cárcel?",
  ui_story_31190601_136_dialog_content = "Eso no es importante. Lo importante es que pasé los últimos cinco años preparándome en caso de que tuviera que salir de prisión.",
  ui_story_31190601_137_dialog_content = "Parece que finalmente es hora de darle un buen uso a \"ese\" movimiento...",
  ui_story_31190601_138_dialog_content = "<color=#e8d9bb>Ton, ton, ton...</color>",
  ui_story_31190601_139_dialog_content = "¿Revy? ¿Qué haces en ese rincón de allí?",
  ui_story_31190601_140_dialog_content = "Eso se parece mucho a... <size=45>¡¿Estás cavando un túnel?!</size>",
  ui_story_31190601_141_dialog_content = "¡¡¡Shhh!!! Mantenlo bajo, ¿quieres?",
  ui_story_31190601_142_dialog_content = "Hice los cálculos. Si empiezo a excavar ahora mismo, debería hacer todo el camino de regreso a Gannon City en poco menos de diez años.",
  ui_story_31190601_143_dialog_content = "Una vez que finalmente me abra camino hacia la libertad, ¡incluso los poderes de arriba quedarán impresionados!",
  ui_story_31190601_144_dialog_content = "Y cuando llegue ese día glorioso, levantaré esta espada que me ayudó a escapar, miraré hacia la lluvia torrencial y gritaré a los cielos:",
  ui_story_31190601_145_dialog_content = "Pero el guardia sigue aquí, Revy. Te ha estado observando cavar todo este tiempo.",
  ui_story_31190601_146_dialog_content = "¿Eh?",
  ui_story_31190601_147_dialog_content = "Además... estoy bastante seguro de que escuchó todo lo que acabas de decir.",
  ui_story_31190601_148_dialog_content = "Excavar, por lo que a mí respecta.",
  ui_story_31190601_149_dialog_content = "Hay muchos prisioneros aquí que quieren cavar para salir. No eres el primero, y seguramente no serás el último.",
  ui_story_31190601_150_dialog_content = "Sin embargo, la mayoría de ellos se dan por vencidos después de unos tres días. Lo más que he visto a un preso aguantar es una semana, e incluso entonces... El \"túnel\" que cavaron era solo un agujero de un metro de profundidad.",
  ui_story_31190601_151_dialog_content = "Wow... ¿Se dieron por vencidos porque era una tarea demasiado difícil?",
  ui_story_31190601_152_dialog_content = "Quiero decir, no realmente. Como dije, este lugar solo está destinado a albergar delincuentes menores. Por lo general, solo los retenemos hasta una semana antes de dejarlos ir.",
  ui_story_31190601_153_dialog_content = "Entonces, ¿estoy atrapada aquí por una semana entera...?",
  ui_story_31190601_154_dialog_content = "Eso no será necesario. Ya solicité un documento de liberación especial del Señor de las Sombras. Puedes venir conmigo ahora.",
  ui_story_31190601_155_dialog_content = "Allura! ¡Has venido a salvarme!",
  ui_story_31190601_156_dialog_content = "¡Sí! ¡Sabía que no estaba destinado a estar encerrado en un lugar como este para siempre!",
  ui_story_31190601_157_dialog_content = "Allura? ¿Qué estás haciendo aquí, de todos los lugares?",
  ui_story_31190601_158_dialog_content = "Si debes saber...",
  ui_story_31190601_159_dialog_content = "<color=#e8d9bb>Hace dos días</color>",
  ui_story_31190601_160_dialog_content = "¿Necesitas algo, abuela? ¿O me encontraste una rara antigüedad en la ciudad de Gannon?",
  ui_story_31190601_161_dialog_content = "No, se trata de Revy.",
  ui_story_31190601_162_dialog_content = "¿Revisar? ¿Qué sucedió?",
  ui_story_31190601_163_dialog_content = "¡Nada! Bueno, todavía no, de todos modos. La vi salir temprano esta mañana, pero estaba vestida completamente diferente a lo habitual.",
  ui_story_31190601_164_dialog_content = "La seguí hasta la puerta, solo para verla subirse a un tren de suministros que se dirigía a Umbraton. ¿Te importaría vigilar a ese chico por mí?",
  ui_story_31190601_165_dialog_content = "¿Por qué no vienes aquí tú mismo? ¿No tienes curiosidad por ver lo que está tramando?",
  ui_story_31190601_166_dialog_content = "Como ella misma no me lo dijo, no quería que yo lo supiera. No soy de los que hacen cosas innecesarias.",
  ui_story_31190601_167_dialog_content = "Ella es libre de hacer lo que quiera. Todo lo que me importa es asegurarme de que esté a salvo.",
  ui_story_31190601_168_dialog_content = "Comprendido. Yo velaré por ella.",
  ui_story_31190601_169_dialog_content = "Te vi en Umbraton justo después de terminar mi conversación con la abuela.",
  ui_story_31190601_170_dialog_content = "Entonces, ¿por qué no apareciste antes? ¡Pensé que me quedaría atrapada aquí por una semana!",
  ui_story_31190601_171_dialog_content = "Para empezar, cuando te vi molestando a ese patrullero con una señal de tránsito... honestamente quise fingir que ni siquiera te conocía.",
  ui_story_31190601_172_dialog_content = "Además, tenía asuntos mucho más urgentes en ese momento. Habría perdido una oportunidad única en la vida de ver una antigüedad única si hubiera decidido interferir en tu pequeño truco.",
  ui_story_31190601_173_dialog_content = "Además, dado lo insignificante que era tu delito, pensé que solo te encerrarían por un día o dos con otros delincuentes igualmente insignificantes.",
  ui_story_31190601_174_dialog_content = "Eso es mucho más seguro que dejar que te vuelvas loco por las calles de Umbraton, para ser honesto. Después de todo, nadie en esta cárcel tiene ninguna posibilidad contra ti.",
  ui_story_31190601_175_dialog_content = "(Ella pensó que hasta ahora... honestamente, ella es parcialmente responsable de esta situación...)",
  ui_story_31190601_176_dialog_content = "Nunca supe que podías ser tan fría, Allura. ¡Duele!",
  ui_story_31190601_177_dialog_content = "Bueno, como una persona fría, supongo que debería darme la vuelta e irme ahora mismo.",
  ui_story_31190601_178_dialog_content = "¡E-Espera, no te vayas! Me equivoqué, ahora ¿podrías sacarme de aquí? ¡Me muero por comer algo de la comida de la abuela ahora mismo!",
  ui_story_31190601_179_dialog_content = "Bueno, yo también extraño su cocina...",
  ui_story_31190601_180_dialog_content = "Si te llevo de vuelta a la ciudad de Gannon, podría pedirte una comida como pago por este trabajito suyo.",
  ui_story_31190601_181_dialog_content = "¡Apúntame!",
  ui_story_31190601_182_dialog_content = "No nos hemos sentado juntos para una de las comidas legendarias de la abuela en mucho tiempo. Esto realmente me trae recuerdos del Dunefire Strike...",
  ui_story_31190601_183_dialog_content = "¡Hoy tengo que ponerme al día con todas las comidas que me he perdido estos últimos días!",
  ui_story_31190601_184_dialog_content = "Esta comida podría haberse combinado con un poco de salsa picante Super Blazing...",
  ui_story_31190601_185_dialog_content = "revivir...",
  ui_story_31190601_186_dialog_content = "¡No me rendiré tan fácilmente! ¡Una vez que haya comido hasta saciarme, seguiré persiguiendo la salsa picante de mis sueños!",
  ui_story_31190601_187_dialog_content = "<color=#FFB400>Salsa Picante Súper Ardiente</color>... ¡Un día, serás mía!",
  ui_story_31190602_1_dialog_content = "Esta es una prueba, así como un juego de alegría sin igual.",
  ui_story_31190602_2_dialog_content = "Gronru, Oficial Técnico de la Federación Illumina, te invita formalmente a participar en este juego.",
  ui_story_31190602_3_dialog_content = "No cuesta nada jugar y no hay formularios que llenar. Todo lo que necesitas hacer es sostener mi última pieza de tecnología de vanguardia, e incluso puedes cobrar una tarifa publicitaria por tus esfuerzos.",
  ui_story_31190602_4_dialog_content = "Con este dispositivo, podrás proteger a los débiles, así como a todos en Illumina e incluso al mundo.",
  ui_story_31190602_5_dialog_content = "Entonces, ¿qué estás esperando? ¡Actúa y únete a la Patrulla Eclipsite ahora!",
  ui_story_31190602_6_dialog_content = "Me alegra que estés aquí, señorita Revy.",
  ui_story_31190602_7_dialog_content = "Espero que no te moleste que pregunte, pero ¿no te parece sospechosa la carta?",
  ui_story_31190602_8_dialog_content = "¡Lo hace! Pero si puedo proteger a los débiles como un verdadero héroe, estoy dispuesto a jugar este juego.",
  ui_story_31190602_9_dialog_content = "Entonces tendrás que cambiarte a tu nuevo atuendo para el comercial.",
  ui_story_31190602_10_dialog_content = "¿Eh? ¿Traje nuevo?",
  ui_story_31190602_11_dialog_content = "Esta ropa... ¡Es <size=45>ridículamente pesada!</size>",
  ui_story_31190602_12_dialog_content = "¡Siento que me estoy asfixiando! ¿Cómo se supone que proteja a los niños en esta situación?!",
  ui_story_31190602_13_dialog_content = "Entonces, ¿qué papel tienes en mente para mí? Puedes decírmelo, ¿verdad?",
  ui_story_31190602_14_dialog_content = "¡Lo sabrás cuando llegue el oficial Gronru!",
  ui_story_31190602_15_dialog_content = "Oye, PlayerName!",
  ui_story_31190602_16_dialog_content = "Revy? ¿Así que tú eres el otro intérprete, eh?",
  ui_story_31190602_17_dialog_content = "¡Esas prendas te quedan muy geniales!",
  ui_story_31190602_18_dialog_content = "¿En serio? Porque me siento como una tortuga atrapada en su caparazón.",
  ui_story_31190602_19_dialog_content = "¿Dónde está tu traje nuevo?",
  ui_story_31190602_20_dialog_content = "¿Quién sabe? Todo depende de Gronru, aparentemente.",
  ui_story_31190602_21_dialog_content = "¿Eh? ¡Oye, mira ese gran gabinete allá! ¿Es ahí donde guardan las cámaras y esas cosas?",
  ui_story_31190602_22_dialog_content = "¡Espera! ¡Mantén tus manitas lejos de mis Materiales Experimentales de Grado S!",
  ui_story_31190602_23_dialog_content = "¡Oh, gracias a Dios! Si esto se arruinara, ¡todo el comercial estaría acabado!",
  ui_story_31190602_24_dialog_content = "Ejem, parece que todos están presentes y contabilizados.",
  ui_story_31190602_25_dialog_content = "Jejeje, ¡ahora finalmente puedo revelar mi último invento! ¡Trata de no asustarte demasiado!",
  ui_story_31190602_26_dialog_content = "¡Deleita tus ojos con la aspiradora Eclipsita! ¡Siéntete libre de saltar y gritar ahora, si quieres!",
  ui_story_31190602_27_dialog_content = "Si me ayuda a matar Eclipsites y proteger a los débiles, ¡entonces eso es suficiente para mí!",
  ui_story_31190602_28_dialog_content = "Espera, ¿entonces tu \"última pieza de tecnología de vanguardia\" es solo una aspiradora?!",
  ui_story_31190602_29_dialog_content = "¡Oye, retira eso ahora mismo! Se llama la Aspiradora Eclipsite, ¡muchas gracias!",
  ui_story_31190602_30_dialog_content = "¿Cómo puedes ser tan ignorante?",
  ui_story_31190602_31_dialog_content = "¡Oye, se siente bastante bien en mis manos! ¿Cómo lo uso?",
  ui_story_31190602_32_dialog_content = "Esta ha sido modificada para parecerse a tu Alter-Cuchilla. En cuanto a cómo usarla, te lo explicaré justo antes de comenzar a disparar.",
  ui_story_31190602_33_dialog_content = "Ustedes dos ya deberían haberlo descubierto, ¿verdad? ¡Quiero que usen la Aspiradora de Eclipsites para ayudarme a grabar un video promocional!",
  ui_story_31190602_34_dialog_content = "¿Y somos los únicos dos actores?",
  ui_story_31190602_35_dialog_content = "¡Sí! Mi video promocional no necesita tantas personas.",
  ui_story_31190602_36_dialog_content = "(En realidad, ustedes dos son las únicas personas que aparecieron... Todos los demás pensaron que esto era una broma.)",
  ui_story_31190602_37_dialog_content = "Entonces, ¿quién interpreta al personaje principal?",
  ui_story_31190602_38_dialog_content = "Eso sería... Revy!",
  ui_story_31190602_39_dialog_content = "Entonces, ¿qué hay de mí?",
  ui_story_31190602_40_dialog_content = "Vas a interpretar al Eclipsite que embosca a Revy, solo para ser completamente destruido por su aspiradora Eclipsite.",
  ui_story_31190602_41_dialog_content = "¡Objeto!",
  ui_story_31190602_42_dialog_content = "¡Anulado!",
  ui_story_31190602_43_dialog_content = "Acabo de recordar algo, oficial Gronru. ¿No deberíamos maquillar a Revy antes de comenzar a filmar?",
  ui_story_31190602_44_dialog_content = "¡Déjame eso a mí! Jejeje, ¡esto va a ser divertido!",
  ui_story_31190602_45_dialog_content = "Urgh—Esto se siente realmente extraño.",
  ui_story_31190602_46_dialog_content = "¡No te preocupes! Esto es de lo mejor, aunque no tenga ni idea de qué es.",
  ui_story_31190602_47_dialog_content = "Creo que debería encargarme de esto, oficial Gronru.",
  ui_story_31190602_48_dialog_content = "Mira, las fosas nasales de Revy están llenas de maquillaje ahora.",
  ui_story_31190602_49_dialog_content = "<size=45>¡Ahhh—Achu—</size>",
  ui_story_31190602_50_dialog_content = "¡De ninguna manera, esto es demasiado divertido! ¡Solo déjame hacerlo!",
  ui_story_31190602_51_dialog_content = "Un poco más aquí, un poco más allá, ¡y listo!",
  ui_story_31190602_52_dialog_content = "¡Es perfecto! ¡A veces incluso me sorprendo a mí mismo!",
  ui_story_31190602_53_dialog_content = "Mmm, creo que deberías dejar que Siobhan se encargue del maquillaje de Revy esta vez.",
  ui_story_31190602_54_dialog_content = "<color=#e8d9bb>Después de un segundo cambio de imagen, los dos actores ensayan sus líneas antes de aprender a usar la aspiradora.</color>",
  ui_story_31190602_55_dialog_content = "Tres, dos, uno, ¡acción!",
  ui_story_31190602_56_dialog_content = "Me pregunto qué tan bien funciona mi nueva aspiradora?",
  ui_story_31190602_57_dialog_content = "Wow, es tan poderoso. Se siente como... Un arma de grado S en el primer nivel.",
  ui_story_31190602_58_dialog_content = "Estas líneas son terribles. ¿Estás seguro de que está bien?",
  ui_story_31190602_59_dialog_content = "No se puede evitar. El oficial Gronru los escribió ella misma.",
  ui_story_31190602_60_dialog_content = "¡Es hora de tu parte!",
  ui_story_31190602_61_dialog_content = "<size=45>Silbido—</size>",
  ui_story_31190602_62_dialog_content = "¿Un Eclipsite? ¡Prepárate para morir!",
  ui_story_31190602_63_dialog_content = "¡Arrodíllate ante el impresionante poder de mi Aspiradora Eclipsite!",
  ui_story_31190602_64_dialog_content = "Ugh, supongo que debería involucrarme un poco más.",
  ui_story_31190602_65_dialog_content = "(¿Eh? No me estoy moviendo, entonces por qué... ¿Por qué mi cuerpo empieza a...)",
  ui_story_31190602_66_dialog_content = "¡Aaaahhhh—Es... Es que me va a succionar!",
  ui_story_31190602_67_dialog_content = "¡Tiempo fuera! ¡Tiempo fuera! Gronru, ¡corten!",
  ui_story_31190602_68_dialog_content = "¡Mis pantalones! ¡Mis pantalones están siendo succionados!",
  ui_story_31190602_69_dialog_content = "¡No te detengas ahora! ¡Sigue adelante!",
  ui_story_31190602_70_dialog_content = "<color=#e8d9bb>La succión de la aspiradora crea un poderoso torbellino dentro de la habitación.</color>",
  ui_story_31190602_71_dialog_content = "<color=#e8d9bb>Rápidamente comienza a absorber todo lo que está a la vista, incluido el gabinete de Materiales Experimentales de Grado S de Gronru.</color>",
  ui_story_31190602_72_dialog_content = "Hiss-",
  ui_story_31190602_73_dialog_content = "¡¡Graaaaaaahh!!",
  ui_story_31190602_74_dialog_content = "¡¿Qué hace un Eclipsite aquí?!",
  ui_story_31190602_75_dialog_content = "¡Sigue filmando! ¡Esta es la parte más importante!",
  ui_story_31190602_76_dialog_content = "¡¿Hablas en serio?!",
  ui_story_31190602_77_option_content = "Directo Revy",
  ui_story_31190602_78_dialog_content = "Revy! Ahora es el momento de aprovechar bien esa Aspiradora de Eclipsites!",
  ui_story_31190602_79_dialog_content = "¡Haz que sienta el mismo dolor y desesperación que acabo de sentir yo!",
  ui_story_31190602_80_option_content = "Escóndete detrás de Revy",
  ui_story_31190602_81_dialog_content = "Ese Eclipsite... ¡Viene directo hacia nosotros!",
  ui_story_31190602_82_dialog_content = "¡Ahhh-!",
  ui_story_31190602_83_dialog_content = "¡Rayos! Por mucho que quiera luchar, tendré que dejar esto en manos de Revy.",
  ui_story_31190602_84_dialog_content = "La fuente de energía está bien y también el ángulo. ¡Activando la aspiradora Eclipsite!",
  ui_story_31190602_85_dialog_content = "¡Te protegeré, PlayerName!",
  ui_story_31190602_86_dialog_content = "¿¿¿???",
  ui_story_31190602_87_dialog_content = "Hiss-",
  ui_story_31190602_88_dialog_content = "Deja de resistirte tanto, ¡apestoso Eclipsite!",
  ui_story_31190602_89_dialog_content = "Revy¡Baja el ángulo en quince grados y apunta a sus pies para que pierda el equilibrio!",
  ui_story_31190602_90_dialog_content = "Eres historia, ¡Eclipsite!",
  ui_story_31190602_91_dialog_content = "Graaaaaah—",
  ui_story_31190602_92_dialog_content = "Y así, nuestra joven heroína protege a la persona más importante para ella.",
  ui_story_31190602_93_dialog_content = "Incluso un amenazante Eclipsite no es más que una mota de polvo cuando se enfrenta al poder de limpieza de la aspiradora Eclipsite.",
  ui_story_31190602_94_dialog_content = "¿Sueñas con convertirte en un héroe a los ojos de los demás? ¿Deseas proteger a tus seres queridos y derrotar a los Eclipsites con facilidad?",
  ui_story_31190602_95_dialog_content = "Entonces, levanta el teléfono ahora mismo, llama a la línea directa del Laboratorio de Investigación de Illumina y ¡ordena el tuyo hoy!",
  ui_story_31190602_96_dialog_content = "Aspiradora Eclipsite, nadie puede resistirse a ella después de usarla.",
  ui_story_31190602_97_dialog_content = "Confía en la aspiradora Eclipsite para hacer el trabajo.",
  ui_story_31190602_98_dialog_content = "Tenga en cuenta: los pedidos solo se pueden realizar entre las 3 PM y las 4 PM, ya que Gronru está ocupado jugando el resto del tiempo.",
  ui_story_31190602_99_dialog_content = "¡Corte—!",
  ui_story_31190602_100_dialog_content = "¡Eso fue perfecto! ¡Estaría llamando al laboratorio ahora mismo si viera esto!",
  ui_story_31190602_101_dialog_content = "¿No estás de acuerdo, Siobhan?",
  ui_story_31190602_102_dialog_content = "Um... ¡Ajá!",
  ui_story_31190602_103_dialog_content = "Uf... Estoy vencido.",
  ui_story_31190602_104_dialog_content = "Ahora que la misión principal está resuelta, ¡es hora de algunas misiones secundarias!",
  ui_story_31190602_105_dialog_content = "¡Vamos a tomar algunas fotos promocionales!",
  ui_story_31190602_106_dialog_content = "Antes de continuar, ¿podemos hablar sobre ese Eclipsite de hace un momento?! ¿Qué hacía en tu laboratorio?!",
  ui_story_31190602_107_dialog_content = "Necesitaba algo para hacer tu actuación un poco más realista, así que contraté a algunas personas para que atraparan uno para mí.",
  ui_story_31190602_108_dialog_content = "Bastante increíble, ¿verdad? Mi invento es tan genial que debería solicitar una patente.",
  ui_story_31190602_109_dialog_content = "¡Tomaré uno! ¿Cuánto cuesta?",
  ui_story_31190602_110_dialog_content = "¿Eh? ¿N-No me digas que en realidad te gusta esto, Revy?!",
  ui_story_31190602_112_dialog_content = "Hará que derrotar a los Eclipsites sea aún más fácil, lo que significa que podré protegerte aún mejor. Eso debería acercarme un paso más a convertirme en un verdadero héroe.",
  ui_story_31190602_113_dialog_content = "Normalmente te cobraría por esto, pero haré una excepción esta vez.",
  ui_story_31190602_114_dialog_content = "Asegúrate de hacer un buen trabajo promocionando mi Aspiradora Eclipsite, Revy!",
  ui_story_31190602_115_dialog_content = "Déjamelo a mí."
}
return config
